section.pre:
[role] { color: navy; }
[role="notice"] { color: navy; }
[class~="warning"] { color: red; }
[lang|="en"] { font-family: serif; }
[href^="https"] { color: blue; }
[href$=".pdf"] { color: purple; }
[data-kind*="reference"] { color: teal; }
[role="notice" i] { color: navy; }

@namespace svg url("http://www.w3.org/2000/svg");

svg|rect { color: navy; }
*|rect { color: teal; }
|rect { color: gray; }
